# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.46.0/ankra-cli-darwin-arm64"
      sha256 "aadde6cb7a8e9446ef0347384a7d53175ca7920ed8170178e81fcf763e536564"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.46.0/ankra-cli-darwin-amd64"
      sha256 "35ed6a471ef682d4fecbc0340dc89c6c0f33eb93d41cc4ad65d9ddf82355013a"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.46.0/ankra-cli-linux-arm64"
      sha256 "38da4dbfa80190f6e41e8dc38e28cc6ed42ee6e42679ce0cf69c332f4b54629b"
    end
    on_intel do
